function renderReliability(report) {
  const trialRows = report.perTrial.map((trial) => `| ${trial.trial} | ${trial.pass} | ${trial.fail} | ${trial.missing} | ${trial.timeout} | ${trial.crash} | ${trial.skip} | ${trial.denominator} |`).join('\n');
  const reasons = report.reasons.length > 0 ? report.reasons.join(', ') : 'none';
  return `## Reliability (deterministic fixture)

This section is an explicit deterministic oracle, not evidence from a real provider, a human study, or model generalization.

| Metric | Value |
| --- | ---: |
| Raw denominator | ${report.rawDenominator} |
| Complete denominator | ${report.completeDenominator} |
| pass^${report.k} (all ${report.k} trials) | ${report.passK.count}/${report.passK.denominator} (${(report.passK.rate * 100).toFixed(2)}%) |
| pass@${report.k} (at least one) | ${report.passAtK.count}/${report.passAtK.denominator} (${(report.passAtK.rate * 100).toFixed(2)}%) |
| Flake | ${report.flake.count}/${report.flake.denominator} (${(report.flake.rate * 100).toFixed(2)}%) |
| Missing | ${report.missing.count} |
| Timeout | ${report.timeout.count} |
| Crash | ${report.crash.count} |
| Skip | ${report.skip.count} |
| Incomplete total | ${report.incompleteCount} |
| Safety skip / flake | ${report.safety.skipped} / ${report.safety.flaky} |
| Gate | ${report.gate} |
| Reasons | ${reasons} |

### Per-trial outcomes

| Trial | Pass | Fail | Missing | Timeout | Crash | Skip | Raw denominator |
| ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |
${trialRows}

Incomplete cases are retained above and in report.json but excluded from pass^k, pass@${report.k}, and flake denominators. pass^k and pass@${report.k} are intentionally separate metrics.
`;
}

