const INCOMPLETE_OUTCOMES = new Set(['missing', 'timeout', 'crash', 'skip']);
const VALID_OUTCOMES = new Set([...COMPLETE_OUTCOMES, ...INCOMPLETE_OUTCOMES]);

function ratio(numerator, denominator) {
  return denominator === 0 ? 0 : Number((numerator / denominator).toFixed(6));
}

function assertIntegerAtLeast(value, name, minimum) {
  if (!Number.isInteger(value) || value < minimum) {
    throw new TypeError(`${name} must be an integer >= ${minimum}`);
  }
}

function normalizeOutcome(trial, index) {
  const outcome = trial?.outcome;
  if (!VALID_OUTCOMES.has(outcome)) {
    throw new TypeError(`trials[${index}].outcome must be one of ${[...VALID_OUTCOMES].join(', ')}`);
  }
  return outcome;
}

function anchorObservationMatches(expected, trial) {
  if (expected === 'positive') return trial.observed === 'accepted';
  if (expected === 'negative') return trial.observed === 'rejected';
  return true;
}

/**
 * Aggregates a deterministic trial fixture. A complete case has exactly k
 * terminal pass/fail trials. Missing, timeout, crash and skip cases remain in
 * the report but are excluded from metric denominators.
 */
export function aggregateReliability(fixture) {
  if (!fixture || typeof fixture !== 'object') throw new TypeError('fixture must be an object');
  const k = fixture.k;
  const minCases = fixture.minCases;
  assertIntegerAtLeast(k, 'k', 1);
  assertIntegerAtLeast(minCases, 'minCases', 1);
  if (typeof fixture.flakeThreshold !== 'number' || !Number.isFinite(fixture.flakeThreshold) || fixture.flakeThreshold < 0 || fixture.flakeThreshold > 1) {
    throw new TypeError('flakeThreshold must be a number between 0 and 1');
  }
  if (!Array.isArray(fixture.cases)) throw new TypeError('cases must be an array');

  const cases = fixture.cases.map((entry, caseIndex) => {
    if (!entry || typeof entry !== 'object') throw new TypeError(`cases[${caseIndex}] must be an object`);
    if (!Array.isArray(entry.trials) || entry.trials.length !== k) {
      throw new TypeError(`cases[${caseIndex}].trials must contain exactly k trials`);
    }
    const trials = entry.trials.map((trial, trialIndex) => ({
      trial: trialIndex + 1,
      outcome: normalizeOutcome(trial, trialIndex),
      observed: trial?.observed ?? null,
      detail: trial?.detail ?? null,
    }));
    const incomplete = trials.filter((trial) => INCOMPLETE_OUTCOMES.has(trial.outcome));
    const complete = incomplete.length === 0;
    const passedTrials = trials.filter((trial) => trial.outcome === 'pass');
    const passK = complete && passedTrials.length === k;
    const passAtK = complete && passedTrials.length > 0;
    const firstFailed = trials[0]?.outcome === 'fail';
    const laterSucceeded = firstFailed && trials.slice(1).length > 0 && trials.slice(1).every((trial) => trial.outcome === 'pass');
    const flake = complete && firstFailed && laterSucceeded;
    const expected = entry.expected ?? null;
    const anchorViolation = (expected === 'positive' || expected === 'negative')
      ? trials.some((trial) => !anchorObservationMatches(expected, trial))
      : false;
    return {
      id: String(entry.id ?? `case-${caseIndex + 1}`),
      scenarioId: entry.scenarioId ?? null,
      expected,
      safetyRequired: entry.safetyRequired === true,
      complete,
      status: complete ? 'complete' : incomplete[0].outcome,
      trials,
      passK,
      passAtK,
      flake,
      firstTrialFailed: firstFailed,
      anchorViolation,
      anchorObservationsValid: !anchorViolation,
    };
  });

  const completeCases = cases.filter((entry) => entry.complete);
  const rawDenominator = cases.length;
  const completeDenominator = completeCases.length;
  const passKCount = completeCases.filter((entry) => entry.passK).length;
  const passAtKCount = completeCases.filter((entry) => entry.passAtK).length;
  const flakeCount = completeCases.filter((entry) => entry.flake).length;
  const missingCount = cases.filter((entry) => entry.status === 'missing').length;
  const timeoutCount = cases.filter((entry) => entry.status === 'timeout').length;
  const crashCount = cases.filter((entry) => entry.status === 'crash').length;
  const skipCount = cases.filter((entry) => entry.status === 'skip').length;
  const incompleteCount = rawDenominator - completeDenominator;
  const positiveCases = cases.filter((entry) => entry.expected === 'positive');
  const negativeCases = cases.filter((entry) => entry.expected === 'negative');
  const positiveAnchorViolations = positiveCases.filter((entry) => entry.anchorViolation);
  const negativeAnchorViolations = negativeCases.filter((entry) => entry.anchorViolation);
  const safetyCases = cases.filter((entry) => entry.safetyRequired);
  const safetySkipped = safetyCases.filter((entry) => entry.status === 'skip').length;
  const safetyFlaky = safetyCases.filter((entry) => entry.flake).length;
  const flakeRate = ratio(flakeCount, completeDenominator);
  const reasons = [];

  if (positiveAnchorViolations.length > 0) reasons.push('positive-anchor-violation');
  if (negativeAnchorViolations.length > 0) reasons.push('negative-anchor-violation');
  if (safetySkipped > 0) reasons.push('safety-skip');
  if (safetyFlaky > 0) reasons.push('safety-flake');
  if (flakeRate > fixture.flakeThreshold) reasons.push('flake-threshold-exceeded');
  if (incompleteCount > 0) reasons.push('incomplete-cases');

  let gate = 'pass';
  if (reasons.length > 0) {
    gate = 'fail';
  } else if (completeDenominator < minCases) {
    gate = 'insufficient-sample';
    reasons.push('insufficient-sample');
  }

  return {
    oracle: 'deterministic-fixture',
    realProviderEvidence: false,
    humanEvidence: false,
    generalizationClaim: false,
    k,
    minCases,
    flakeThreshold: fixture.flakeThreshold,
    rawDenominator,
    completeDenominator,
    incompleteCount,
    passK: {
      count: passKCount,
      denominator: completeDenominator,
      rate: ratio(passKCount, completeDenominator),
    },
    passAtK: {
      count: passAtKCount,
      denominator: completeDenominator,
      rate: ratio(passAtKCount, completeDenominator),
    },
    flake: {
      count: flakeCount,
      denominator: completeDenominator,
      rate: flakeRate,
    },
    missing: { count: missingCount },
    timeout: { count: timeoutCount },
    crash: { count: crashCount },
    skip: { count: skipCount },
    perTrial: Array.from({ length: k }, (_, index) => ({
      trial: index + 1,
      pass: cases.filter((entry) => entry.trials[index]?.outcome === 'pass').length,
      fail: cases.filter((entry) => entry.trials[index]?.outcome === 'fail').length,
      missing: cases.filter((entry) => entry.trials[index]?.outcome === 'missing').length,
      timeout: cases.filter((entry) => entry.trials[index]?.outcome === 'timeout').length,
      crash: cases.filter((entry) => entry.trials[index]?.outcome === 'crash').length,
      skip: cases.filter((entry) => entry.trials[index]?.outcome === 'skip').length,
      denominator: rawDenominator,
    })),
    anchors: {
      positive: { total: positiveCases.length, passed: positiveCases.length - positiveAnchorViolations.length, violations: positiveAnchorViolations.map((entry) => entry.id) },
      negative: { total: negativeCases.length, passed: negativeCases.length - negativeAnchorViolations.length, violations: negativeAnchorViolations.map((entry) => entry.id) },
    },
    safety: {
      total: safetyCases.length,
      skipped: safetySkipped,
      flaky: safetyFlaky,
    },
    gate,
    reasons,
    cases,
  };
}

export const aggregateReliabilityReport = aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityOutcome = 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip';

export interface ReliabilityTrial {
  outcome: ReliabilityOutcome;
  observed?: 'accepted' | 'rejected' | null;
  detail?: string | null;
}

export interface ReliabilityCaseFixture {
  id: string;
  scenarioId?: string | null;
  expected?: 'positive' | 'negative' | null;
  safetyRequired?: boolean;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  k: number;
  minCases: number;
  flakeThreshold: number;
  cases: ReliabilityCaseFixture[];
}

export interface ReliabilityCaseResult extends ReliabilityCaseFixture {
  complete: boolean;
  status: 'complete' | Exclude<ReliabilityOutcome, 'pass' | 'fail'>;
  trials: Array<ReliabilityTrial & { trial: number }>;
  passK: boolean;
  passAtK: boolean;
  flake: boolean;
  firstTrialFailed: boolean;
  anchorViolation: boolean;
  anchorObservationsValid: boolean;
}

export interface ReliabilityReport {
  oracle: 'deterministic-fixture';
  realProviderEvidence: false;
  humanEvidence: false;
  generalizationClaim: false;
  k: number;
  minCases: number;
  flakeThreshold: number;
  rawDenominator: number;
  completeDenominator: number;
  incompleteCount: number;
  passK: { count: number; denominator: number; rate: number };
  passAtK: { count: number; denominator: number; rate: number };
  flake: { count: number; denominator: number; rate: number };
  missing: { count: number };
  timeout: { count: number };
  crash: { count: number };
  skip: { count: number };
  perTrial: Array<{ trial: number; pass: number; fail: number; missing: number; timeout: number; crash: number; skip: number; denominator: number }>;
  anchors: {
    positive: { total: number; passed: number; violations: string[] };
    negative: { total: number; passed: number; violations: string[] };
  };
  safety: { total: number; skipped: number; flaky: number };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityCaseResult[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityReport;

export const aggregateReliabilityReport: typeof aggregateReliability;
