import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@') ? name.replace('/', '\\') : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0 ? 1 : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function renderReliability(report) {
  const trialRows = report.perTrial.map((trial) => `| ${trial.trial} | ${trial.pass} | ${trial.fail} | ${trial.missing} | ${trial.timeout} | ${trial.crash} | ${trial.skip} | ${trial.denominator} |`).join('\n');
  const reasons = report.reasons.length > 0 ? report.reasons.join(', ') : 'none';
  return `## Reliability (deterministic fixture)

This section is an explicit deterministic oracle, not evidence from a real provider, a human study, or model generalization.

| Metric | Value |
| --- | ---: |
| Raw denominator | ${report.rawDenominator} |
| Complete denominator | ${report.completeDenominator} |
| pass^${report.k} (all ${report.k} trials) | ${report.passK.count}/${report.passK.denominator} (${(report.passK.rate * 100).toFixed(2)}%) |
| pass@${report.k} (at least one) | ${report.passAtK.count}/${report.passAtK.denominator} (${(report.passAtK.rate * 100).toFixed(2)}%) |
| Flake | ${report.flake.count}/${report.flake.denominator} (${(report.flake.rate * 100).toFixed(2)}%) |
| Missing | ${report.missing.count} |
| Timeout | ${report.timeout.count} |
| Crash | ${report.crash.count} |
| Skip | ${report.skip.count} |
| Incomplete total | ${report.incompleteCount} |
| Safety skip / flake | ${report.safety.skipped} / ${report.safety.flaky} |
| Gate | ${report.gate} |
| Reasons | ${reasons} |

### Per-trial outcomes

| Trial | Pass | Fail | Missing | Timeout | Crash | Skip | Raw denominator |
| ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |
${trialRows}

Incomplete cases are retained above and in report.json but excluded from pass^k, pass@${report.k}, and flake denominators. pass^k and pass@${report.k} are intentionally separate metrics.
`;
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`).join('\n');
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

${renderReliability(report.reliability)}
## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- The reliability fixture is an internal deterministic oracle. It does not establish real-provider, human, or generalization claims.
`;
}

const start = performance.now();
const [scenarioRegistry, hostApi, e2eFixture, schemaText, a11yText, reliabilityFixtureText] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliability = aggregateReliability(JSON.parse(reliabilityFixtureText));
const registeredFixtureScenarioIds = reliability.cases.map((entry) => entry.scenarioId).filter(Boolean);
reliability.scenarioRegistry = {
  source: 'shared/agent-dev/scenarios.ts',
  registeredScenarioCount: scenarioIds.length,
  fixtureScenarioIds: registeredFixtureScenarioIds,
  fixtureScenarioIdsNotInRegistry: registeredFixtureScenarioIds.filter((id) => !scenarioIds.includes(id)),
};
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
  reliability,
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability aggregation boundary

## Scope

Reliability aggregation is an internal Agent Dev benefit-report concern. It reuses the Agent Dev scenario registry and the deterministic fixture; it is not a new metrics platform and exposes no user-visible interface or configuration.

## Metric definitions

- `pass^k` is the proportion of complete cases for which all `k` trials pass.
- `pass@k` is the proportion of complete cases for which at least one of the `k` trials passes.
- These metrics must be labeled and stored separately. `pass^k` must never be renamed, rendered, or interpreted as `pass@k`.
- A case is complete only when all `k` trials have a terminal `pass` or `fail` outcome. `missing`, `timeout`, `crash`, and `skip` make the case incomplete.
- Incomplete cases are excluded from metric denominators, but their raw count, per-case status, and trial records remain visible in the report.
- Raw denominator is the number of fixture cases. Complete denominator is the number of complete cases.

## Flake and gates

A flake is a complete case whose first trial failed and whose fixed subsequent retries all passed. The first failure is retained. A retry success does not erase the first failure or independently convert the case into pass^k.

The fixture preregisters `k`, `minCases`, and `flakeThreshold` before evaluation. The design sample is `k=3`, at least 20 complete cases, and a fixture flake threshold of 0.10. A complete-case count below `minCases` produces `gate=insufficient-sample`; it must never be reported as PASS.

Positive anchors must be accepted in every trial. Negative anchors must be rejected in every trial. Any anchor violation is `gate=fail`. Safety-required cases must have zero skips and zero flakes. Missing, timeout, crash, and skip cases, anchor violations, safety violations, or a flake rate above the preregistered threshold fail the gate.

## Evidence boundary

The JSON fixture is an explicitly labelled deterministic oracle. Its output must not claim real-provider behavior, human performance, or model generalization. No product default, product lock, approval semantics, dependency, timer, or automation is changed by this boundary.
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# Task: E01 reliability aggregation

## Objective

Extend the existing Agent Dev benefit report with deterministic reliability aggregation without creating another metrics platform or changing product behavior.

## Preconditions

The fixture at `shared/agent-dev/reliability-fixture.json` preregisters:

- `k`: 3
- `minCases`: 20 complete cases
- `flakeThreshold`: 0.10

Scenario identifiers continue to be sourced from the existing Agent Dev scenario registry at `shared/agent-dev/scenarios.ts`.

## Required report fields

The report must contain, as separate fields:

- raw denominator;
- complete denominator;
- `pass^k` count, denominator, and rate;
- `pass@k` count, denominator, and rate;
- flake count, denominator, and rate;
- missing, timeout, crash, and skip counts;
- per-trial success and terminal-status counts;
- positive and negative anchor outcomes;
- safety skip and flake counts;
- gate and machine-readable reasons;
- per-case trial details, including first failures and incomplete records.

## Acceptance behavior

1. Complete a case only if all `k` trials are terminal pass/fail results.
2. Exclude incomplete cases from pass^k, pass@k, and flake denominators while retaining them in raw and per-case output.
3. Compute pass^k only from all-pass cases and pass@k separately from cases with at least one pass.
4. Detect flake as first failure followed by fixed successful retries; preserve the first failure.
5. Fail the gate for a positive anchor that was not always accepted, a negative anchor that was not always rejected, any safety skip/flake, incomplete cases, or a flake rate above the fixture threshold.
6. Return `insufficient-sample` when fewer than `minCases` complete cases exist and no stronger failure exists. Never label a small sample PASS.
7. Label the fixture as a deterministic oracle and make no real-provider, human, or generalization claim.

## Verification

Run the existing scoped unit/type/lint/harness checks without adding tests to runtime code. Confirm credential scanning has zero hits and verify SHA256SUMS can be read back. Record results in the E01 closure document.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 — Deterministic reliability aggregation

## Scope delivered

The existing Agent Dev benefit report now includes deterministic `pass^k`, `pass@k`, per-trial outcome, flake, incomplete-status, and positive/negative anchor aggregation. The implementation reuses `shared/agent-dev/scenarios.ts` and `shared/agent-dev/reliability-fixture.json`; it does not introduce a metrics platform.

The fixture preregisters `k=3`, `minCases=20`, and `flakeThreshold=0.10`. A complete case contains three terminal pass/fail trials. Missing, timeout, crash, and skip cases remain visible by case and status but are excluded from the pass^k, pass@k, and flake denominators.

## Semantic decisions

- `pass^k` means all `k` trials pass.
- `pass@k` means at least one trial passes.
- The two metrics are reported separately.
- Flake means trial 1 failed and all fixed retries passed. The first failure remains in the report and the case does not become pass^k.
- Positive anchors require acceptance in every trial; negative anchors require rejection in every trial. Any violation fails the gate.
- Safety-required cases must have zero skip and zero flake.
- Fewer than 20 complete cases is `insufficient-sample`, never PASS.

## Fixture interpretation

The checked-in fixture is an internal deterministic oracle. It intentionally retains missing, timeout, crash, skip, and first-failure examples, plus an anchor violation, so that the report demonstrates explicit gate failure rather than hiding adverse records. Its scenario identifiers are checked against the existing registry and reported as such.

This fixture is not real-provider output, a human evaluation, a benchmark of deployment traffic, or evidence of model generalization. It makes no claim about any of those properties.

## Product and repository boundary

Only internal evaluation reporting and its supporting internal library, fixture, specifications, and closure record changed. There is no user-visible API or configuration change, no product default change, no product-lock change, no approval-semantics change, no dependency change, and no scheduled automation. README files therefore do not require modification for this internal-only change.

## Acceptance record

The required clean-candidate fast gate is: focused unit tests, runtime/core type checks, scoped lint, and harness validate/dry-run. Credential scanning must report zero hits, and `SHA256SUMS` must be readable and match the reviewed candidate files.

These checks are repository-owner verification requirements and are not executed by the implementation at runtime. The report implementation performs no network request, reads no test at runtime, and starts no external process.
